import { expect, test } from "../../fixtures";

test.describe("review queue access", () => {
  test("members cannot see the review queue", { tag: "@REV-04" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");

    // Act
    const response = await member.get("/api/review-queue");

    // Assert
    expect(response.status(), await response.text()).toBe(403);
    const body = await response.json();
    expect(body.error.code, JSON.stringify(body)).toBe("forbidden");
  });
});
